import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import LoginHeader from "../header/header"; // Composant de l'en-tête
import '../../styles.css';

const Login = ({ setIsAuthenticated }) => {
  const [username, setUsername] = useState("");
  const [password, setPassword] = useState("");
  const [error, setError] = useState("");
  const [displayName, setDisplayName] = useState(""); // Pour afficher le prénom et nom
  const navigate = useNavigate();

  const handleLogin = async () => {
    try {
      // Envoi uniquement du username au backend pour la recherche LDAP
      const response = await fetch("http://localhost:8000/ldapsearch", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({ username }), // On envoie uniquement le username
      });

      if (!response.ok) {
        throw new Error("Échec de la requête LDAP.");
      }

      const data = await response.json();
      console.log("Réponse LDAP :", data);

      // Si la recherche LDAP réussit, afficher le prénom et nom
      if (data.displayName) {
        setDisplayName(data.displayName);  // Affichage du prénom et nom
        setIsAuthenticated(true); // Authentification réussie
        navigate("/homePage"); // Redirection vers la page d'accueil
      } else {
        setError("Utilisateur introuvable ou mot de passe incorrect.");
      }
    } catch (error) {
      console.error("Erreur lors de la recherche LDAP :", error);
      setError("Une erreur s'est produite. Veuillez réessayer.");
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    // Validation simple des champs
    if (!username || !password) {
      setError("Veuillez remplir tous les champs.");
      return;
    }

    if (password !== "password") {
      setError("Le mot de passe est incorrect.");
      return;
    }

    // Appel à la fonction de login qui effectue la recherche LDAP
    await handleLogin();
  };

  return (
    <>
      <div className="min-h-screen bg-cover bg-center bg-landscape flex flex-col items-center">
        <div className="w-full">
          <LoginHeader />
        </div>
        <div className="flex items-center w-1/2 justify-center max-w-[60%] mx-auto mt-8 bg-[rgba(0,0,0,0.7)] rounded-2xl shadow-lg p-8">
          <form onSubmit={handleSubmit} className="flex flex-col items-center w-full">
            <div
              className="bg-primary rounded-full w-32 h-32 mb-12 bg-center bg-cover bg-pfp"
            />
            <div className="flex flex-col items-center mb-6">
              <label htmlFor="username" className="text-white mb-2">
                Identifiant :
              </label>
              <input
                type="text"
                id="username"
                value={username}
                onChange={(e) => setUsername(e.target.value)}
                required
                className="w-[130%] px-4 py-2 border border-gray-300 rounded-md"
              />
            </div>
            <div className="flex flex-col items-center mb-6">
              <label htmlFor="password" className="text-white mb-2">
                Mot de passe :
              </label>
              <input
                type="password"
                id="password"
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                required
                className="w-[130%] px-4 py-2 border border-gray-300 rounded-md"
              />
            </div>
            <button
              type="submit"
              className="btn-primary transition duration-300"
            >
              Se connecter
            </button>
            {error && (
              <p className="text-red-500 text-right text-sm mt-4">{error}</p>
            )}
            {displayName && (
              <div className="mt-4 text-white">
                <p>Bienvenue, {displayName} !</p>
              </div>
            )}
          </form>
        </div>
      </div>
    </>
  );
};

export default Login;
